<script setup>
import { onMounted,ref,watch } from 'vue'
import { useRoute,RouterLink } from 'vue-router'
import { assetUrl,useLearningStore } from '../api'
const route=useRoute(),api=useLearningStore(),item=ref(null),error=ref(''),loading=ref(true)
async function load(){loading.value=true;error.value='';try{item.value=await api.request(`materials/${encodeURIComponent(route.params.id)}`)}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load);watch(()=>route.params.id,load)
</script>
<template><div class="content-page detail-page"><RouterLink class="back-dark" to="/materials">← 返回素材阅读馆</RouterLink><div v-if="loading" class="state-box">正在读取素材…</div><div v-else-if="error" class="state-box error">{{error}} <button @click="load">重试</button></div><template v-else><div class="section-top"><p class="eyebrow">LIBRARY / {{item.collection}}</p><span>{{item.pages}} 页</span></div><h2>{{item.title}}</h2><p class="page-lead">{{item.filename}} · 用户提供素材</p><div class="detail-actions"><a class="primary-action" :href="assetUrl(item.fileUrl)" target="_blank" rel="noopener">查看原 PDF ↗</a><a v-if="item.videoUrl" class="secondary-action" :href="assetUrl(item.videoUrl)" target="_blank" rel="noopener">播放配套视频</a><RouterLink v-if="item.textStatus==='novel_lessons'" class="secondary-action" to="/novel">进入小说词汇</RouterLink></div><div v-if="item.audioUrl" class="media-panel"><h3>配套音频</h3><audio controls :src="assetUrl(item.audioUrl)">浏览器不支持音频播放。</audio></div><article v-if="item.japanese" class="reader-page"><div class="reader-label">日语原文</div><p class="reading-text">{{item.japanese}}</p></article><details v-if="item.translation" class="vocab-panel"><summary>展开中文译文（原材料）</summary><p class="reading-text">{{item.translation}}</p></details><div v-if="item.textStatus==='scan_only'" class="source-note">这份素材为扫描 PDF，目前保留原件供阅读；未核对的识别结果不会用于出题。</div><div v-if="item.metadata?.note" class="source-note">{{item.metadata.note}}</div><p v-if="item.metadata?.attribution" class="source-caption">原作者：{{item.metadata.attribution}}</p><p class="source-caption">原文件校验值：{{item.sha256}}</p></template></div></template>
